Here's a C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int firstNum, secondNum, numElements;

    // Prompt the user for input
    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> firstNum >> secondNum;

    // Validate the first two integers
    if (firstNum < 0 || secondNum < 0) {
        throw runtime_error("Both integers must be non-negative.");
    }

    // Prompt the user for the number of sequence elements
    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    // Validate the number of sequence elements
    if (numElements <= 0) {
        throw runtime_error("The number of sequence elements must be positive.");
    }

    // Generate the Fibonacci sequence
    int sequence[numElements];
    sequence[0] = firstNum;
    sequence[1] = secondNum;
    for (int i = 2; i < numElements; i++) {
        sequence[i] = fibonacci(i, firstNum, secondNum);
    }

    // Output the generated sequence
    cout << "Fibonacci sequence: ";
    for (int i = 0; i < numElements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

