    % Convert input phrase to uppercase
    phrase = strtoupper(phrase);

    % Initialize empty string to store the Morse Code representation
    morse_code = '';

    % Loop through each character in the input phrase
    for i = 1:length(phrase)
        % Map each character to its Morse Code representation
        switch phrase(i)
