Here's a simple C++ program implementing the bubble sort algorithm for sorting an integer array:

```cpp
#include <iostream>
#include <vector>

void bubble_sort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    bubble_sort(arr);
    for (auto it : arr) {
        std::cout << it << " ";
    }
    return 0;
}
```

