Here's a MATLAB code that identifies the tense of a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence, ' ');

    % Initialize variables
    main_verb = '';
    auxiliary_verb = '';
    tense = '';

    % Loop through each word
    for i = 1:length(words)
        % Check if the word is a verb
        if strcmp(words{i}, 'be') || strcmp(words{i}, 'have') || strcmp(words{i}, 'do') || ...
            strcmp(words{i}, 'did') || strcmp(words{i}, 'does') || strcmp(words{i}, 'can') || ...
            strcmp(words{i}, 'could') || strcmp(words{i}, 'will') || strcmp(words{i}, 'would') || ...
            strcmp(words{i}, 'shall') || strcmp(words{i}, 'should') || strcmp(words{i}, 'may') || ...
            strcmp(words{i}, 'might') || strcmp(words{i}, 'must') || strcmp(words{i}, 'ought')

            % If it is, check if it's the main verb or an auxiliary verb
            if i == length(words)
                main_verb = words{i};
            else
                auxiliary_verb = words{i};
            end
        end
    end

    % Determine the tense based on the main verb and auxiliary verb
    if main_verb == 'be' && auxiliary_verb == 'be'
        tense = 'present simple';
    elseif main_verb == 'be' && auxiliary_verb == 'have'
        tense = 'present perfect';
    elseif main_verb == 'be' && auxiliary_verb == 'do'
        tense = 'present continuous';
    elseif main_verb == 'have' && auxiliary_verb == 'have'
