Here's an example of a generic REST service wrapper class in C# that includes auth token handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Text;

public abstract class RestServiceWrapper<T>
{
    protected readonly string _baseAddress;
    protected readonly string _authToken;

    public RestServiceWrapper(string baseAddress, string authToken)
    {
        _baseAddress = baseAddress;
        _authToken = authToken;
    }

    public async Task<T> GetAsync(string endpoint)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync($"{_baseAddress}/{endpoint}");
            if (response.IsSuccessStatusCode)
            {
                return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
            }
            else
            {
                throw new Exception($"Failed to get data from {endpoint}: {response.ReasonPhrase}");
            }
        }
    }

    public async Task<T> PostAsync(string endpoint, object data)
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
            var response = await client.PostAsync($"{_baseAddress}/{endpoint}", content);
            if (response.IsSuccessStatusCode)
            {
                return JsonConvert.DeserializeObject<T>(await response.Content.ReadAsStringAsync());
            }
            else
            {
                throw new Exception($"Failed to post data to {endpoint}: {response.ReasonPhrase}");
            }
        }
    }
}
```

