Here's a simple Google Apps Script that searches for a place name in a column and stores its latitude and longitude in other columns:

```javascript
function searchPlace() {
  var spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = spreadsheet.getActiveSheet();

  // Define the column where you want to search for place names
  var searchColumn = 1; // Assuming the first column is A

  // Define the column where you want to store the latitude
  var latitudeColumn = 2; // Assuming the second column is B

  // Define the column where you want to store the longitude
  var longitudeColumn = 3; // Assuming the third column is C

  // Get the data from the search column
  var searchData = sheet.getRange(searchColumn, 1, sheet.getLastRow()).getValues();

  // Loop through the search data
  for (var i = 0; i < searchData.length; i++) {
    var placeName = searchData[i][0];

    // Search for the place name using the Google Maps API
    var url = "https://maps.googleapis.com/maps/api/geocode/json?address=" + placeName + "&key=YOUR_API_KEY";
    var response = UrlFetchApp.fetch(url);
    var data = JSON.parse(response);

    // Extract the latitude and longitude from the response
    var latitude = data.results[0].geometry.location.lat;
    var longitude = data.results[0].geometry.location.lng;

    // Store the latitude and longitude in the respective columns
    sheet.getRange(i + 1, latitudeColumn).setValue(latitude);
    sheet.getRange(i + 1, longitudeColumn).setValue(longitude);
  }
}
```

Replace `YOUR_API_KEY` with your actual Google Maps API key. This script will search for place names in the specified column, extract their latitude and longitude using the Google Maps API, and store the results in the respective columns.

