Here's a simple C function that converts an array of command-line arguments (`argv`) to a null-terminated string:

```c
#include <stdio.h>
#include <string.h>

char *argv_to_cstring(int argc, char *argv[]) {
    int i;
    char *result = malloc(argc * sizeof(char) + 1); // +1 for the null terminator

    if (!result) {
        return NULL;
    }

    for (i = 0; i < argc; i++) {
        strcat(result, argv[i]);
        if (i != argc - 1) {
            strcat(result, " ");
        }
    }

    result[argc] = '\0'; // Ensure the string is null-terminated

    return result;
}

int main(int argc, char *argv[]) {
    char *cstring = argv_to_cstring(argc, argv);
    if (cstring) {
        printf("Converted argument vector to C string: %s\n", cstring);
        free(cstring);
    } else {
        printf("Failed to allocate memory for the C string.\n");
    }

    return 0;
}
```

