```powershell
# Define the function to check if an SID occurs only in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $sidHistory = @()

    # Get the SIDHistory of all users and groups in the domain
    Get-ADUser -Filter {(ObjectCategory -eq "person")} -Properties SIDHistory | ForEach-Object {
        $sidHistory += $_.SIDHistory
    }

    Get-ADGroup -Filter {(ObjectCategory -eq "group")} -Properties SIDHistory | ForEach-Object {
        $sidHistory += $_.SIDHistory
    }

    # Check if the provided SID is present in the SIDHistory of any user or group in the domain
    return ($sidHistory | Where-Object { $_ -eq $sid })
}

# Define the function to recursively check folders for ACLs with SIDs that occur only in the SIDHistory
function CheckFolderACLs($folderPath) {
    Get-Acl -Path $folderPath | ForEach-Object {
        $acl = $_.Access

        # Check each access control entry (ACE) for an SID that occurs only in the SIDHistory
        $acl | ForEach-Object {
            if ($_.IdentityReference -match "(?i)$sid") {
                if (CheckSIDInSIDHistory($_.IdentityReference)) {
                    Write-Host "The ACL of $folderPath contains an SID ($sid) that occurs only in the SIDHistory of any user or group in the domain."
                }
            }
        }

        # Recursively check subfolders
        if ($folderPath -contains "\") {
            CheckFolderACLs($folderPath + "\*")
        }
    }
}

# Call the function with the root folder path
$rootFolderPath = "C:\Your_Root_Folder_Path"
CheckFolderACLs($rootFolderPath)
```

